            face.boldAdvances = mv_boliAdv; face.boldOtherAdvances = mv_boliOther
            face.naturalHeight = 1.6113; face.baseline = 1.1392

        case "khmer ui":
            face.advances = khmer_uiAdv
            face.otherAdvances = khmer_uiOther
            face.boldAdvances = khmer_uiBoldAdv
            face.boldOtherAdvances = khmer_uiBoldOther
            face.naturalHeight = 1.1318; face.baseline = 0.9219

        case "dubai":
            face.advances = dubaiAdv
            face.otherAdvances = dubaiOther
            face.boldAdvances = dubaiBoldAdv
            face.boldOtherAdvances = dubaiBoldOther
            face.naturalHeight = 1.6880; face.baseline = 1.1290

        case "urdu typesetting":
            face.advances = urdu_typesettingAdv
            face.otherAdvances = urdu_typesettingOther
            face.boldAdvances = urdu_typesettingBoldAdv
            face.boldOtherAdvances = urdu_typesettingBoldOther
            face.naturalHeight = 1.7031; face.baseline = 1.3701

        case "copperplate gothic bold":
            face.advances = copperplate_gothic_boldAdv
            face.otherAdvances = copperplate_gothic_boldOther
            face.naturalHeight = 1.1128; face.baseline = 0.8853

        case "copperplate gothic light":
            face.advances = copperplate_gothic_lightAdv
            face.otherAdvances = copperplate_gothic_lightOther
            face.naturalHeight = 1.0991; face.baseline = 0.8926

        case "goudy old style":
            face.advances = goudy_old_styleAdv
            face.otherAdvances = goudy_old_styleOther
            face.boldAdvances = goudy_old_styleBoldAdv
            face.boldOtherAdvances = goudy_old_styleBoldOther
            face.italicAdvances = goudy_old_styleItalicAdv
            face.naturalHeight = 1.2002; face.baseline = 0.9629

        default: break
        }
    }
}
